    slides: "スライド",
    doc: "文書",
    table: "表",
    wbs: "WBS",
    arch: "構成図",
    map: "論点マップ",
    explain: "解説ページ",
    memo: "案件メモ",
    tool: "ツール呼び出し",
    plan: "計画",
    code: "コード",
