    karte: "karte", "karte-update": "karte",
    flow: "flow",
    slides: "slides", deck: "slides",
    doc: "doc", markdown: "doc", md: "doc",
    table: "table", tsv: "table", csv: "table",
    wbs: "wbs", arch: "arch", map: "map", explain: "explain",
    memo: "memo",
