    推奨: { fill: "#FFF1D6", stroke: "#B8892B", text: "#6E4B00" },
    要確認: { fill: "#FFF6E0", stroke: "#8A5A00", text: "#8A5A00" },
    リスク: { fill: "#FDECEA", stroke: "#B3261E", text: "#8E1B15" },
    済: { fill: "#E6F2EC", stroke: "#1A6B35", text: "#1A6B35" },
