      const stroke = isRoot ? C.navy : t ? t.stroke : C.navy;
      out.push(`<rect x="${D.r1(p.x)}" y="${D.r1(p.y)}" width="${p.w}" height="${D.r1(p.h)}" rx="${isRoot ? 8 : 6}" fill="${fill}" stroke="${stroke}" stroke-width="${p.n.tags.includes("推奨") ? 2.4 : 1.2}"/>`);
