        out.push(`<rect x="${D.r1(bx)}" y="${D.r1(p.y + p.h - 18)}" width="${D.r1(w)}" height="14" rx="7" fill="#fff" stroke="${tc.stroke}" stroke-width="0.8"/>${D.textLines([tag], bx + w / 2, p.y + p.h - 11, { size: 10, color: tc.text })}`);
