          const bk = ["case", "_控え", `qa.json.${stamp()}-${Date.now() % 100000}`];
          await A().fs.write(bk, raw);
          say(`case/qa.json を読めませんでした（${e.message}）。元のファイルを ${bk.join("/")} に退避し、空の質問箱で始めます`, "err");
